import{_ as o,o as i,c as a,ae as l}from"./chunks/framework.qNV68s4p.js";const p=JSON.parse('{"title":"排障","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/troubleshooting.md","filePath":"zh/guide/troubleshooting.md","lastUpdated":1776335312000}'),t={name:"zh/guide/troubleshooting.md"};function r(n,e,d,c,h,s){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="排障" tabindex="-1">排障 <a class="header-anchor" href="#排障" aria-label="Permalink to &quot;排障&quot;">​</a></h1><p>这一页汇总集成和使用 SweetEditor 时最常见的问题。</p><h2 id="滚动时-decoration-一直重复追加" tabindex="-1">滚动时 Decoration 一直重复追加 <a class="header-anchor" href="#滚动时-decoration-一直重复追加" aria-label="Permalink to &quot;滚动时 Decoration 一直重复追加&quot;">​</a></h2><p>原因：</p><ul><li>可视区范围型 decoration provider 使用了 <code>DecorationApplyMode.Merge</code></li></ul><p>修复方式：</p><ul><li>对按行、按可见区重算的 decoration，优先使用 <code>DecorationApplyMode.ReplaceRange</code></li></ul><h2 id="completion-不弹" tabindex="-1">Completion 不弹 <a class="header-anchor" href="#completion-不弹" aria-label="Permalink to &quot;Completion 不弹&quot;">​</a></h2><p>检查项：</p><ul><li>是否通过 <code>addCompletionProvider()</code> 注册了 provider</li><li>是否手动触发了 completion，或者 provider 支持触发字符</li><li>当前是否处于 linked editing 等可能冲突的状态</li></ul><h2 id="inline-suggestion-不显示" tabindex="-1">Inline Suggestion 不显示 <a class="header-anchor" href="#inline-suggestion-不显示" aria-label="Permalink to &quot;Inline Suggestion 不显示&quot;">​</a></h2><p>检查项：</p><ul><li>是否调用了 <code>controller.inlineSuggestions().show(...)</code></li><li><code>line</code> 和 <code>column</code> 是否是合法的 0-based 位置</li><li>是否在文档加载完成之后再显示 suggestion</li></ul><h2 id="theme-不生效" tabindex="-1">Theme 不生效 <a class="header-anchor" href="#theme-不生效" aria-label="Permalink to &quot;Theme 不生效&quot;">​</a></h2><p>检查项：</p><ul><li>是否调用了 <code>controller.applyTheme(theme)</code></li><li>是否稳定使用 <code>rememberEditorAppearance()</code> 或 <code>rememberEditorTheme()</code></li><li>行为相关配置是否错误地写进了 themeContent，而不是 <code>EditorSettings</code></li></ul><h2 id="编辑器外观和预期不一致" tabindex="-1">编辑器外观和预期不一致 <a class="header-anchor" href="#编辑器外观和预期不一致" aria-label="Permalink to &quot;编辑器外观和预期不一致&quot;">​</a></h2><p>检查项：</p><ul><li>是否在控制器就绪后调用了 <code>controller.applyTheme(theme)</code></li><li><code>themeContent</code> 中使用的键是否属于当前解析器支持的字段</li><li>行为类配置是否错误地写到了 themeContent，而不是 <code>EditorSettings</code></li><li>自定义 <code>textStyles</code> 名称是否与高亮数据中的样式别名一致</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./architecture">架构</a></li><li><a href="./faq">FAQ</a></li><li>英文 <a href="./../../guide/api-cookbook">API Cookbook</a></li></ul>',21)])])}const m=o(t,[["render",r]]);export{p as __pageData,m as default};
